const { seg, eio, lerp } = kit;
// Ravana: a leather puppet in profile, facing left. Feet at (0,0); head about 1000 units up. Jaw and front arm turn on their own pivots.
Object.assign(W, {
  ravanaHead(cls) {
    const O = W.O;
    let s = '<g class="' + cls + '-head">' +
      '<path d="M-160 -740 Q-180 -950 0 -1020 Q180 -950 160 -740 Q130 -900 0 -955 Q-130 -900 -160 -740 Z" style="fill:var(--gold);' + O + '"/>' + W.lace(-140, -800, -60, -962, 8, 4) + W.lace(60, -962, 140, -800, 8, 4) +
      '<path d="M30 -812 Q118 -776 106 -690 Q138 -630 102 -556 Q82 -588 66 -630 Q48 -690 18 -716 Z" style="fill:var(--ink)"/>' +
      '<path d="M54 -812 Q-30 -832 -66 -798 L-74 -758 L-100 -735 Q-94 -724 -82 -722 L-76 -712 Q-40 -699 0 -690 L42 -700 Q76 -745 54 -812 Z" style="fill:var(--skinR);' + O + '"/>' +
      '<g class="' + cls + '-jaw"><path d="M-76 -712 Q-85 -700 -79 -690 Q-83 -676 -70 -667 Q-40 -658 -4 -672 L22 -700 Q-30 -699 -76 -712 Z" style="fill:var(--skinR);' + O + '"/><path d="M-79 -700 Q-66 -693 -52 -698" style="fill:none;stroke:var(--redDeep);stroke-width:5;stroke-linecap:round"/></g>' +
      '<path d="M-90 -716 Q-52 -742 -12 -716 Q22 -700 42 -744 Q48 -768 28 -772 Q40 -750 22 -733 Q2 -716 -22 -729 Q-54 -746 -90 -716 Z" style="fill:var(--ink)"/>' +
      '<path d="M-68 -752 Q-48 -770 -26 -754 Q-48 -740 -68 -752 Z" style="fill:var(--second);' + O + '"/><circle cx="-46" cy="-754" r="7" style="fill:var(--ink)"/>' +
      '<path d="M-72 -752 Q-48 -774 -20 -756 L-2 -764" style="fill:none;stroke:var(--ink);stroke-width:4"/>' +
      '<path d="M-78 -774 Q-48 -792 -10 -778" style="fill:none;stroke:var(--ink);stroke-width:8;stroke-linecap:round"/>' +
      '<path d="M-58 -805 H-20 M-60 -798 H-18" style="stroke:var(--second);stroke-width:3.5;stroke-linecap:round"/>' +
      '<circle cx="26" cy="-708" r="20" style="fill:none;stroke:var(--gold);stroke-width:8"/><circle cx="26" cy="-685" r="7" style="fill:var(--red);' + O + '"/>' +
      '<path d="M-70 -808 L62 -818 L64 -848 L-66 -840 Z" style="fill:var(--gold);' + O + '"/>' + W.lace(-56, -825, 52, -833, 9, 4) +
      '<path d="M60 -832 Q104 -862 96 -914 Q82 -872 60 -860 Z M-66 -826 Q-108 -854 -102 -906 Q-86 -866 -66 -854 Z" style="fill:var(--gold);' + O + '"/>' +
      '<path d="M-56 -842 L54 -848 L40 -902 L-44 -898 Z" style="fill:var(--goldDeep);' + O + '"/><circle cx="-2" cy="-873" r="12" style="fill:var(--red);' + O + '"/>' +
      '<path d="M-42 -900 L38 -904 L26 -954 L-30 -952 Z" style="fill:var(--gold);' + O + '"/>' + W.lace(-30, -925, 26, -927, 5, 3.5) +
      '<path d="M-28 -952 L24 -954 L-2 -1016 Z" style="fill:var(--goldDeep);' + O + '"/><circle cx="-2" cy="-1020" r="9" style="fill:var(--red);' + O + '"/>';
    return s + '</g>';
  },
  ravana(cls) {
    const O = W.O, back = 'color-mix(in srgb, var(--skinR) 78%, var(--ink))';
    let scales = '';
    for (let y = -588; y <= -440; y += 26) for (let x = -66; x <= 56; x += 28) scales += 'M' + (x + (y / 26 % 2 ? 14 : 0)) + ' ' + y + ' q14 16 28 0 ';
    return '<g class="' + cls + '">' +
      '<path d="M98 -330 L150 900" style="stroke:var(--ink);stroke-width:4"/>' +
      '<path d="M40 -612 L76 -600 L98 -462 L66 -456 Z M66 -470 L96 -466 L112 -342 L84 -338 Z" style="fill:' + back + ';' + O + '"/><circle cx="98" cy="-326" r="18" style="fill:' + back + ';' + O + '"/><rect x="62" y="-482" width="40" height="14" style="fill:var(--gold);' + O + '"/>' +
      '<path d="M8 -160 L46 -160 L56 -14 L20 -14 Z M-42 -160 L-4 -160 L-40 -14 L-76 -14 Z" style="fill:var(--skinR);' + O + '"/>' +
      '<path d="M18 -14 L58 -14 L74 0 L4 0 Z M-78 -14 L-38 -14 L-34 0 L-110 0 Z" style="fill:var(--goldDeep);' + O + '"/><path d="M14 -40 H54 M-72 -40 H-36" style="stroke:var(--gold);stroke-width:9"/>' +
      '<path d="M-96 -392 L96 -392 L124 -150 Q0 -118 -128 -150 Z" style="fill:var(--red);' + O + '"/>' +
      '<path d="M-40 -380 L-60 -180 M0 -380 L-6 -160 M40 -380 L56 -180" style="stroke:var(--redDeep);stroke-width:5;fill:none"/>' +
      '<path d="M-120 -192 Q0 -162 118 -192 L124 -150 Q0 -118 -128 -150 Z" style="fill:var(--gold);' + O + '"/>' + W.lace(-108, -164, 108, -164, 14, 4) +
      '<path d="M-24 -384 L2 -384 L12 -200 L-16 -190 Z" style="fill:var(--gold);' + O + '"/>' +
      '<path d="M-82 -632 Q-98 -520 -88 -392 L92 -392 Q102 -520 72 -632 Z" style="fill:var(--skinR);' + O + '"/>' +
      '<circle class="' + cls + '-glow" cx="-4" cy="-515" r="150" style="fill:var(--second);opacity:0"/>' +
      '<path d="M-80 -612 Q-92 -520 -82 -420 Q0 -398 86 -420 Q96 -520 70 -612 Q0 -588 -80 -612 Z" style="fill:var(--gold);' + O + '"/>' +
      '<path d="' + scales + '" style="fill:none;stroke:var(--goldDeep);stroke-width:3"/>' +
      '<circle cx="-4" cy="-520" r="26" style="fill:var(--red);' + O + '"/><circle cx="-4" cy="-520" r="9" style="fill:var(--second)"/>' + W.lace(-76, -600, 66, -600, 12, 4) +
      '<rect x="-94" y="-412" width="188" height="26" style="fill:var(--goldDeep);' + O + '"/>' + W.lace(-86, -399, 86, -399, 14, 3.5) +
      '<path d="M-44 -676 L22 -676 L32 -628 L-48 -628 Z" style="fill:var(--skinR);' + O + '"/><path d="M-62 -636 Q-10 -588 52 -636" style="fill:none;stroke:var(--gold);stroke-width:11"/>' + W.lace(-50, -622, 40, -622, 8, 3) +
      W.ravanaHead(cls) +
      '<g class="' + cls + '-arm"><path d="M-212 -452 L-262 900" style="stroke:var(--ink);stroke-width:4"/>' +
      '<path d="M-82 -618 L-46 -598 L-104 -484 L-134 -500 Z M-134 -500 L-104 -484 L-192 -440 L-206 -466 Z" style="fill:var(--skinR);' + O + '"/>' +
      '<path d="M-206 -470 Q-234 -482 -238 -456 Q-228 -438 -200 -438 Z" style="fill:var(--skinR);' + O + '"/><path d="M-196 -472 L-186 -436" style="stroke:var(--gold);stroke-width:9"/>' +
      '<path d="M-84 -566 L-116 -548" style="stroke:var(--gold);stroke-width:12"/><ellipse cx="-66" cy="-612" rx="32" ry="22" style="fill:var(--gold);' + O + '"/></g>' +
      '</g>';
  },
});
W.RIG.ravana = { jaw: [-10, -705], arm: [-60, -605] };

kit.scene('kavach', {
  init(kit) {
    this.s = W.shot(kit, {
      id: 'kavach', bg: 'court', back: W.guard(120, 0.9, false) + W.guard(800, 0.9, true),
      cast: [{ who: 'ravana', x: 470, y: 975, s: 0.82 }],
      cam: [1.0, 1.05, 459, 560, 470, 540],
      arm: (t, i, talk) => 18 + 10 * Math.sin(t * 1.4) + (talk ? 6 : 0),
      lines: [[0.9, 3.5, 'सुनो… यह कवच ब्रह्मा जी का वरदान है।', 0, 0]],
    });
  },
  render(t) { this.s.render(t); },
});
